        descriptions={'en': ''},
        aliases={'en': ['']},
        statements=statements,
        sitelinks={'': {}},
        _updated=datetime.now(),
    )


def test_full():
    e = make_entity(
        {
            'P1': [
                {'mainsnak': {'datavalue': {'value': {'content': 'a'}}}},
                {'mainsnak': {'datavalue': {'value': {'content': 'b'}}}},
            ]
        }
    )
    assert e.get_statement_values('P1') == ['a', 'b']


def test_order_and_skipping():
    e = make_entity(
        {
            'P1': [
                {'mainsnak': {'datavalue': {'value': {'content': 'a'}}}},
                {},
                {'mainsnak': {}},
                {'mainsnak': {'datavalue': {'value': {}}}},
                {'mainsnak': {'datavalue': {'value': {'content': 3}}}},
                {'mainsnak': {'datavalue': {'value': {'content': ''}}}},
                'not-a-dict',
                {'value': {'content': 'z'}},
                {'mainsnak': {'datavalue': {'value': {'content': None}}}},
                {'mainsnak': {'datavalue': {'value': 'plain'}}},
                {'mainsnak': {'datavalue': {'value': {'content': 'y'}}}},
            ]
        }
    )
    assert e.get_statement_values('P1') == ['a', 'z', 'y']


def test_missing_property():
    e = make_entity({'P1': [{'value': {'content': 'a'}}]})
    assert e.get_statement_values('P2') == []
    assert e.get_statement_values('') == []
    e2 = make_entity({'': {}})  # legacy shape used by existing tests
    assert e2.get_statement_values('') == []
